import{_ as o,l as r,o as e,c as l,v as t,p as d,x as s,d as c,i as p,S as n}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"缓存雪崩与热键","description":"","frontmatter":{"title":"缓存雪崩与热键","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cache-stampede-hotkey.md","filePath":"cs/cache-stampede-hotkey.md","lastUpdated":1789023840000}'),h={name:"cs/cache-stampede-hotkey.md"};function m(E,a,_,T,A,f){const i=r("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="缓存雪崩与热键" tabindex="-1">缓存雪崩与热键 <a class="header-anchor" href="#缓存雪崩与热键" aria-label="Permalink to &quot;缓存雪崩与热键&quot;">​</a></h1><div class="epigraph"><p>大批键同时过期，或单键被打到一台存储，miss 路径把后端打穿。要错开 TTL、单飞填充、并对热键分片或本地层。</p><footer>—— 据 Nishtala et al., Scaling Memcache at Facebook, NSDI 2013；业界 stampede / dogpile 实践整理</footer></div><p>上一课<a href="/cs/distributed-cache-invalidation">缓存失效</a>的 miss 会打存储。缺口是<strong>miss 同步到来</strong>：雪崩是时间对齐，热键是空间对齐。本课钉缓解，不重写版本 cas。后课限流是更外层的保护，缓存打穿时限流是后备。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>雪崩：同一时刻大量 TTL 到期或重启空缓存，所有读变 miss。热键：流行键的 QPS 超过单存储分片。单飞（singleflight）：同一键并发 miss 只允许一个填充，其余等——租约在 Facebook memcache 里就是这种锁。没有单飞，N 个应用进程 × M 个 worker 对同一 miss 放大成 N×M 次查询。</p><p>缺口：只加机器不加错开与单飞，重启仍是雪崩。只加缓存不加热键分片，单键仍打穿。</p><p><span class="marginnote">dogpile/stampede 是同一现象的两个名字。逻辑时钟课的租约在这里变成填充租约，期限很短。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>TTL 加抖动，避免对齐。预热关键键。分层：进程内缓存挡热键，再分布式缓存，再库。热键拆成多个子键随机读（若语义允许）或复制到多缓存节点。降级：打穿时返回旧值（若还留着 stale-if-error）。</p>',9)),(e(),d(n,null,{default:s(()=>[p(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20MISS%5B%22%E5%B9%B6%E5%8F%91%20miss%22%5D%20--%3E%20SF%5B%22%E5%8D%95%E9%A3%9E%20%2F%20%E5%A1%AB%E5%85%85%E7%A7%9F%E7%BA%A6%22%5D%0A%20%20SF%20--%3E%20ONE%5B%22%E4%B8%80%E6%AC%A1%E6%89%93%E5%AD%98%E5%82%A8%22%5D%0A%20%20TTL%5B%22TTL%20%2B%20%E6%8A%96%E5%8A%A8%22%5D%20--%3E%20SPREAD%5B%22%E9%94%99%E5%BC%80%E8%BF%87%E6%9C%9F%22%5D%0A%20%20HOT%5B%22%E7%83%AD%E9%94%AE%22%5D%20--%3E%20L1%5B%22%E6%9C%AC%E5%9C%B0%E7%BC%93%E5%AD%98%20%2F%20%E5%88%86%E7%89%87%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>不要用全局锁「填充全世界」。锁本身会雪崩。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>与<a href="/cs/failure-detectors">故障检测</a>：存储变慢使填充超时，重试放大，形成活锁。熔断下一课。缓存空窗与发布同时发生（滚动升级后课）是雪崩常见组合。</p><p>本课不把 CDN 流量工程写全。也不写 GPU 热键。</p><p>过期对齐常来自「午夜批任务写同一 TTL」。抖动必须在写填充时做，不是只在配置里写一个常数。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给容量规划公式。后课默认：缓存层必须有单飞与 TTL 抖动；热键有本地层或拆分。限流熔断接在打穿之后当保险丝，不是第一道。超时退避再下一课把重试放大钉死。</p><p>同步 miss 是负载峰值的制造器。缓存的命中率曲线在过期点不连续。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>雪崩：过期/变空对齐；用抖动与预热。</li><li>热键：单飞 + 本地层或拆分。</li><li>填充租约防止 miss 放大。</li><li>出处：Nishtala et al., NSDI 2013；stampede 实践。</li></ul>',10))])}const S=o(h,[["render",m]]);export{B as __pageData,S as default};
